// ─── File: src/main/java/com/bank/sorter/service/TradeSorterService.java ───
package com.bank.sorter.service;

import com.bank.sorter.dto.SortedTradesReport;
import com.bank.sorter.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class TradeSorterService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "EQUITY",    "RELIANCE", new BigDecimal("245050"), 100, "SETTLED"),
        new Trade("TRD-002", "EQUITY",    "TCS",      new BigDecimal("176000"), 50,  "SETTLED"),
        new Trade("TRD-003", "EQUITY",    "RELIANCE", new BigDecimal("490100"), 200, "SETTLED"),
        new Trade("TRD-004", "FIXED_INC", "GOVT-BOND",new BigDecimal("330150"), 300, "SETTLED"),
        new Trade("TRD-005", null,        "WIPRO",    new BigDecimal("33664"),  80,  "SETTLED"),
        new Trade("TRD-006", "FOREX",     "USD-INR",  new BigDecimal("123750"), 150, "SETTLED"),
        new Trade("TRD-007", null,        "HDFC",     new BigDecimal("222037"), 120, "SETTLED"),
        new Trade("TRD-008", "EQUITY",    "INFY",     new BigDecimal("176000"), 90,  "SETTLED")
    );

    public SortedTradesReport sortAllVariations() {
        Map<String, List<String>> results = new LinkedHashMap<>();

        // ═══ 1. SINGLE FIELD: symbol ascending ═══
        results.put("1_symbol_asc", trades.stream()
            .sorted(Comparator.comparing(Trade::symbol))
            .map(this::format).toList());

        // ═══ 2. AMOUNT DESCENDING ═══
        results.put("2_amount_desc", trades.stream()
            .sorted(Comparator.comparing(Trade::amount).reversed())
            .map(this::format).toList());

        // ═══ 3. MULTI-KEY: department asc (nulls last) + amount desc ═══
        results.put("3_dept_nullsLast_amount_desc", trades.stream()
            .sorted(Comparator.comparing(Trade::department,
                    Comparator.nullsLast(Comparator.naturalOrder()))
                .thenComparing(Trade::amount, Comparator.reverseOrder()))
            .map(this::format).toList());

        // ═══ 4. TRIPLE KEY: department asc + amount desc + tradeId asc ═══
        results.put("4_dept_amount_id", trades.stream()
            .sorted(Comparator.comparing(Trade::department,
                    Comparator.nullsLast(Comparator.naturalOrder()))
                .thenComparing(Trade::amount, Comparator.reverseOrder())
                .thenComparing(Trade::tradeId))
            .map(this::format).toList());

        // ═══ 5. PRIMITIVE: comparingInt for quantity (no autoboxing) ═══
        results.put("5_quantity_desc", trades.stream()
            .sorted(Comparator.comparingInt(Trade::quantity).reversed())
            .map(this::format).toList());

        // ═══ 6. NULLS FIRST: null departments at beginning ═══
        results.put("6_dept_nullsFirst", trades.stream()
            .sorted(Comparator.comparing(Trade::department,
                Comparator.nullsFirst(Comparator.naturalOrder())))
            .map(this::format).toList());

        // ═══ 7. TIE-BREAK DEMO: TRD-002 and TRD-008 have same amount (176000) ═══
        results.put("7_tiebreak_amount_then_id", trades.stream()
            .sorted(Comparator.comparing(Trade::amount)
                .thenComparing(Trade::tradeId))
            .map(this::format).toList());

        return new SortedTradesReport(results);
    }

    private String format(Trade t) {
        return t.tradeId() + " [" + (t.department() == null ? "NULL" : t.department())
            + "] " + t.symbol() + " Rs." + t.amount() + " qty=" + t.quantity();
    }
}
