// ─── File: src/test/java/com/bank/sorter/service/ComparatorChainTest.java ───
package com.bank.sorter.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ComparatorChainTest {

    record Item(String dept, int amount, String id) {}

    @Test
    void singleFieldAscending() {
        List<Item> items = List.of(new Item("B", 100, "2"), new Item("A", 200, "1"));
        List<Item> sorted = items.stream().sorted(Comparator.comparing(Item::dept)).toList();
        assertThat(sorted.get(0).dept()).isEqualTo("A");
    }

    @Test
    void thenComparingForTieBreak() {
        List<Item> items = List.of(
            new Item("A", 200, "2"), new Item("A", 100, "1"), new Item("B", 150, "3"));
        List<Item> sorted = items.stream()
            .sorted(Comparator.comparing(Item::dept).thenComparingInt(Item::amount))
            .toList();
        assertThat(sorted.get(0).amount()).isEqualTo(100);  // A with lower amount first
        assertThat(sorted.get(1).amount()).isEqualTo(200);  // A with higher amount second
    }

    @Test
    void reversedOnSpecificFieldOnly() {
        List<Item> items = List.of(
            new Item("A", 200, "2"), new Item("A", 100, "1"), new Item("B", 150, "3"));
        List<Item> sorted = items.stream()
            .sorted(Comparator.comparing(Item::dept)
                .thenComparing(Comparator.comparingInt(Item::amount).reversed()))
            .toList();
        assertThat(sorted.get(0).amount()).isEqualTo(200);  // A: amount DESCENDING
        assertThat(sorted.get(1).amount()).isEqualTo(100);
        assertThat(sorted.get(2).dept()).isEqualTo("B");     // dept still ascending
    }

    @Test
    void nullsLastHandlesNullDepartment() {
        List<Item> items = List.of(new Item(null, 100, "1"), new Item("A", 200, "2"));
        List<Item> sorted = items.stream()
            .sorted(Comparator.comparing(Item::dept,
                Comparator.nullsLast(Comparator.naturalOrder())))
            .toList();
        assertThat(sorted.get(0).dept()).isEqualTo("A");   // non-null first
        assertThat(sorted.get(1).dept()).isNull();          // null last
    }

    @Test
    void nullsFirstHandlesNullDepartment() {
        List<Item> items = List.of(new Item("B", 100, "1"), new Item(null, 200, "2"));
        List<Item> sorted = items.stream()
            .sorted(Comparator.comparing(Item::dept,
                Comparator.nullsFirst(Comparator.naturalOrder())))
            .toList();
        assertThat(sorted.get(0).dept()).isNull();          // null first
        assertThat(sorted.get(1).dept()).isEqualTo("B");
    }

    @Test
    void comparingIntAvoidAutoboxing() {
        List<Item> items = List.of(new Item("A", 300, "1"), new Item("A", 100, "2"));
        List<Item> sorted = items.stream()
            .sorted(Comparator.comparingInt(Item::amount))
            .toList();
        assertThat(sorted.get(0).amount()).isEqualTo(100);
    }

    @Test
    void tieBreakWithSameAmountDifferentId() {
        List<Item> items = List.of(
            new Item("A", 100, "TRD-008"), new Item("A", 100, "TRD-002"));
        List<Item> sorted = items.stream()
            .sorted(Comparator.comparing(Item::dept)
                .thenComparingInt(Item::amount)
                .thenComparing(Item::id))
            .toList();
        assertThat(sorted.get(0).id()).isEqualTo("TRD-002");  // alphabetical tiebreak
        assertThat(sorted.get(1).id()).isEqualTo("TRD-008");
    }

    @Test
    void withoutNullsWrapperThrowsNPE() {
        List<Item> items = List.of(new Item(null, 100, "1"), new Item("A", 200, "2"));
        assertThatThrownBy(() -> items.stream()
            .sorted(Comparator.comparing(Item::dept))  // no nullsFirst/Last!
            .toList())
            .isInstanceOf(NullPointerException.class);
    }
}
